def encode_component(name):
    if name.startswith('.'): name='dot_'+name[1:]
    return name

def encode_path(rel, mode, islink=False, template=False):
    parts=[encode_component(x) for x in rel.split(os.sep) if x not in ('','.','..')]
    if not parts:return ''
    name=parts[-1]
    if islink: name='symlink_'+name
    elif mode & 0o111: name='executable_'+name
    elif mode & 0o200==0: name='readonly_'+name
    elif mode & 0o077==0: name='private_'+name
    if template and not islink:name += '.tmpl'
    parts[-1]=name
    return os.path.join(*parts)

