    for path in paths:
        node = root
        for part in path.split("/"):
            node = node.setdefault(part, {})
        node[terminal] = None
    lines = []
    def walk(node, depth):
        for key in sorted((k for k in node if k is not terminal)):
            lines.append("  " * depth + key)
            walk(node[key], depth + 1)
    walk(root, 0)
    return lines


def handle(command, args, source, destination):
    """Return (exit status, stdout, stderr); args excludes command/global flags."""
    nul = "-0" in args or "--nul-path-separator" in args
    absolute = "--path-style=absolute" in args or "--path-style" in args and args[args.index("--path-style") + 1:args.index("--path-style") + 2] == ["absolute"]
    tree = "-t" in args or "--tree" in args
    includes = None
    excludes = set()
    operands = []
    j = 0
    while j < len(args):
        a = args[j]
        if a in ("--include", "-i", "--exclude", "-x", "--path-style", "-p") and j + 1 < len(args):
            key, val = a, args[j + 1]
            if key in ("--include", "-i"): includes = set(val.split(","))
            elif key in ("--exclude", "-x"): excludes.update(val.split(","))
            j += 2
            continue
        if a.startswith("--include="): includes = set(a.split("=", 1)[1].split(","))
        elif a.startswith("--exclude="): excludes.update(a.split("=", 1)[1].split(","))
        elif a.startswith("--path-style="): pass
        elif a.startswith("-"): pass
        else: operands.append(a)
        j += 1
    root = Path(destination).expanduser().resolve()
    if command == "unmanaged" and not root.exists():
        raw = os.fspath(root)
        return 1, "", f"chezmoi: {raw}: lstat {raw}: no such file or directory\nchezmoi: skip this directory\n"
    known = _managed(source)
    if command == "ignored":
        patterns = _ignored_patterns(source)
        candidates = []
        source_root = Path(source).expanduser()
        for base, dirs, files in os.walk(source_root):
            dirs.sort(); files.sort()
            for n in dirs + files:
                if _source_metadata(n):
                    continue
                src_rel = (Path(base) / n).relative_to(source_root)
                rel = Path(*(target_name(part) for part in src_rel.parts)).as_posix()
                if any(("/" not in rel or "/" in p) and fnmatch.fnmatchcase(rel, p)
                       for p in patterns):
                    candidates.append(rel)
        candidates.sort()
    else:
        candidates = []
        def visit(path):
            rel = path.relative_to(root).as_posix()
            # Managed directories are traversed so unmanaged descendants are
            # still reported. Unmanaged directories are reported as a unit.
            if path.is_dir() and not path.is_symlink() and rel in known:
                for child in sorted(path.iterdir()):
                    visit(child)
            elif rel not in known:
                candidates.append(rel)
        if not operands:
            paths = [root]
        else:
            paths = []
            for operand in operands:
                p = Path(operand).expanduser()
                # chezmoi resolves command line paths against the process cwd,
                # then checks that the resulting path is inside the destination.
                if not p.is_absolute(): p = Path.cwd() / p
                if not p.exists() and not p.is_symlink():
                    raw = os.fspath(p)
                    return 1, "", f"chezmoi: {raw}: lstat {raw}: no such file or directory\nchezmoi: skip this directory\n"
                # Normalize `..` without following a target symlink: links are
                # themselves unmanaged entries and may point outside dest.
                p = Path(os.path.abspath(p))
                try:
                    p.relative_to(root)
                except ValueError:
                    return 1, "", f"chezmoi: {p}: not in {root}\n"
                paths.append(p)
        for path in paths:
            if not path.exists() and not path.is_symlink():
                continue
            if path.is_dir():
                if path == root and not operands:
                    for entry in sorted(path.iterdir()):
                        visit(entry)
                else:
                    visit(path)
            else:
                rel = path.relative_to(root).as_posix()
                if rel not in known: candidates.append(rel)
        candidates = sorted(set(candidates))
        if includes is not None or excludes:
            kept = []
            for rel in candidates:
                p = root / rel
                typ = "symlinks" if p.is_symlink() else "dirs" if p.is_dir() else "files"
                if includes is not None and typ not in includes and not (typ == "dirs" and "directories" in includes):
                    continue
                if typ in excludes or (typ == "dirs" and "directories" in excludes):
                    continue
                kept.append(rel)
            candidates = kept
    if absolute:
        candidates = [(root / p).as_posix() for p in candidates]
    if tree:
        candidates = _tree_lines(candidates)
    sep = "\0" if nul and not tree else "\n"
    out = sep.join(candidates)
    if candidates and not nul: out += "\n"
    if candidates and nul and not tree: out += "\0"
    return 0, out, ""

